-- Closed-deal profit ledger from HUD statements (idempotent)
CREATE TABLE IF NOT EXISTS "ClosedDeal" (
  "id" TEXT NOT NULL,"address" TEXT NOT NULL,"city" TEXT NOT NULL DEFAULT '',"state" TEXT NOT NULL DEFAULT '',
  "closeDate" TEXT NOT NULL,"year" INTEGER NOT NULL,"month" INTEGER NOT NULL,"dealType" TEXT NOT NULL DEFAULT 'assignment',
  "profit" DOUBLE PRECISION NOT NULL,"notes" TEXT NOT NULL DEFAULT '',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "ClosedDeal_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX IF NOT EXISTS "ClosedDeal_address_closeDate_key" ON "ClosedDeal"("address","closeDate");
CREATE INDEX IF NOT EXISTS "ClosedDeal_year_idx" ON "ClosedDeal"("year");
